const profileSlugs={'TCS London Marathon':'london-marathon','Skyline Scotland by UTMB':'skyline-scotland-utmb','Omagh Half Marathon & 5K':'omagh-half-marathon'};
const slugify=name=>races.find(r=>r.name===name)?.slug||profileSlugs[name]||name.toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const card=r=>`<article class="card"><span class="tag">${r.type} · ${r.nation}</span><h3>${r.name}</h3><div class="meta">${r.distance} · ${r.place} · ${r.date}</div><p class="reason">${r.reason}</p><p class="unknown">Elevation: ${r.elevation}. Cut-off: ${r.cutoff}. Travel: ${r.transport}.</p><a href="/races/${slugify(r.name)}/">Profile ↗</a> <a href="${r.source}" target="_blank" rel="noreferrer">Official source ↗</a> <button class="compare" data-name="${r.name}">Add to compare</button></article>`;
function list(){const q=document.querySelector('#search').value.toLowerCase(),n=document.querySelector('#region').value,t=document.querySelector('#type').value;return races.filter(r=>(!q||(`${r.name} ${r.place}`).toLowerCase().includes(q))&&(n==='any'||r.nation===n)&&(t==='any'||r.type===t))};function render(){document.querySelector('#race-list').innerHTML=list().map(card).join('');bind()};let chosen=[];function bind(){document.querySelectorAll('.compare').forEach(b=>b.onclick=()=>{const r=races.find(x=>x.name===b.dataset.name);if(!chosen.includes(r)&&chosen.length<3)chosen.push(r);document.querySelector('#compare-panel').innerHTML=`<table class="compare-table"><tr><th>Detail</th>${chosen.map(x=>`<th>${x.name}</th>`).join('')}</tr>${[['Distance','distance'],['Elevation','elevation'],['Cut-off','cutoff'],['Transport','transport'],['Facilities','facilities']].map(f=>`<tr><th>${f[0]}</th>${chosen.map(x=>`<td>${x[f[1]]}</td>`).join('')}</tr>`).join('')}</table>`})};document.querySelector('#finder-form').onsubmit=e=>{e.preventDefault();const d=document.querySelector('#distance').value,s=document.querySelector('#surface').value;document.querySelector('#finder-results').innerHTML=races.filter(r=>(d==='any'||r.distance.toLowerCase().includes(d.toLowerCase())||(d==='Ultra'&&r.distance.includes('ultra')))&&(s==='any'||r.type===s)).slice(0,6).map(card).join('');bind()};['search','region','type'].forEach(id=>document.querySelector('#'+id).oninput=render);render();
const objectiveCopy={first:'Best read as a starting point for a first event when the published distance and facilities fit. Check current organiser instructions before entering.',pb:'This may suit a PB-focused runner where the surface is appropriate, but no pace or difficulty is inferred from missing data.',scenic:'A scenery-led possibility because the source identifies a trail, park or point-to-point setting. Elevation remains unknown where it is not published.',generous:'A generous time limit is only claimed when the source publishes one. Unknown cut-offs stay unknown.',carfree:'Travel information is available in part. A nearby station or shuttle does not prove race-day timing feasibility.'};
function profile(r){return `<div class="profile-backdrop" id="profile-view" role="dialog" aria-modal="true"><article class="profile"><button class="close-profile" aria-label="Close profile">×</button><span class="tag">${r.type} · ${r.nation}</span><h2>${r.name}</h2><p class="profile-sub">${r.distance} · ${r.place} · ${r.date} edition</p><p>${r.reason}</p><h3>What is verified</h3><dl><dt>Course / surface</dt><dd>${r.type==='road'?'Road course':'Trail or mixed course'}</dd><dt>Elevation</dt><dd>${r.elevation}</dd><dt>Cut-off</dt><dd>${r.cutoff}</dd><dt>Travel</dt><dd>${r.transport}</dd><dt>Facilities</dt><dd>${r.facilities}</dd></dl><p class="unknown">Unknown values are deliberately shown as unknown. This profile does not infer course difficulty, predicted finish time or public-transport feasibility.</p><a class="button dark" href="${r.source}" target="_blank" rel="noreferrer">Read official source ↗</a></article></div>`}
function showProfile(name){const r=races.find(x=>x.name===name);if(!r)return;document.querySelector('#profile-view')?.remove();document.body.insertAdjacentHTML('beforeend',profile(r));document.querySelector('.close-profile').onclick=()=>document.querySelector('#profile-view').remove();document.querySelector('#profile-view').onclick=e=>{if(e.target.id==='profile-view')e.target.remove()}}
const baseBind=bind;bind=function(){baseBind();document.querySelectorAll('.card').forEach(c=>{if(c.querySelector('.profile-button')||c.querySelector('.profile-link'))return;const b=document.createElement('button');b.className='profile-button';b.textContent='View profile';b.dataset.name=c.querySelector('h3').textContent;b.onclick=()=>showProfile(b.dataset.name);c.querySelector('.compare').before(b)});document.querySelectorAll('.compare').forEach(b=>b.textContent=chosen.some(x=>x.name===b.dataset.name)?'Added':'Add to compare')};
const originalSubmit=document.querySelector('#finder-form').onsubmit;document.querySelector('#finder-form').onsubmit=e=>{originalSubmit(e);const objective=document.querySelector('#objective').value;document.querySelectorAll('#finder-results .card').forEach(c=>{const r=races.find(x=>x.name===c.querySelector('h3').textContent);if(r){const p=document.createElement('p');p.className='objective-note';p.textContent=objectiveCopy[objective];c.querySelector('.reason').after(p)}})};
render();
