const finderForm=document.querySelector('#finder-form');
if(!document.querySelector('#advanced-preferences')){const advanced=document.createElement('details');advanced.id='advanced-preferences';advanced.innerHTML='<summary>Refine your shortlist</summary><div class="advanced-grid"><label>Expected finish<select id="finish"><option value="any">Not sure yet</option><option value="beginner">First-time pace</option><option value="steady">Steady recreational pace</option><option value="fast">Faster / PB-focused</option></select></label><label>Travel preference<select id="travel"><option value="any">No preference</option><option value="carfree">Prefer rail, coach or shuttle information</option></select></label></div>';finderForm.insertBefore(advanced,finderForm.querySelector('button'))}
let richCard=r=>{const verified=[`Distance: ${r.distance}`,`Surface: ${r.type==='road'?'Road':'Trail / mixed'}`,r.elevation!=='Not confirmed'?`Elevation: ${r.elevation}`:null,r.cutoff!=='Not confirmed'?`Cut-off: ${r.cutoff}`:null,r.transport!=='Not confirmed'?`Travel: ${r.transport}`:null,r.facilities!=='Not confirmed'?`Facilities: ${r.facilities}`:null].filter(Boolean);const unknown=[r.elevation==='Not confirmed'?'Elevation':null,r.cutoff==='Not confirmed'?'Cut-off':null,r.transport==='Not confirmed'?'Travel timing':null,r.facilities==='Not confirmed'?'Facilities':null].filter(Boolean);const watch=unknown.length?`Check before entering: ${unknown.join(', ')} ${unknown.length===1?'is':'are'} not confirmed.`:'No major practical gaps were identified in the reviewed source.';return `<article class="card"><span class="tag">${r.type} · ${r.nation}</span><h3>${r.name}</h3><div class="meta">${r.distance} · ${r.place} · ${r.date}</div><p class="reason">${r.reason}</p><p class="confidence"><strong>Verified:</strong> ${verified.join(' · ')}</p><p class="watchouts"><strong>Watch out:</strong> ${watch}</p><div class="card-actions"><a class="profile-link" href="/races/${slugify(r.name)}/">Open full profile →</a><a href="${r.source}" target="_blank" rel="noreferrer">Official source ↗</a><button class="compare" data-name="${r.name}">Add to compare</button></div></article>`};
const textCard=richCard;richCard=r=>textCard(r).replace('<span class="tag">',r.image?`<img class="race-card-image" src="${r.image.src}" alt="${r.image.alt}" loading="lazy" width="480" height="218"><span class="tag">`:'<span class="tag">');
render=function(){document.querySelector('#race-list').innerHTML=list().map(richCard).join('');bind()};
finderForm.onsubmit=e=>{e.preventDefault();const d=document.querySelector('#distance').value,s=document.querySelector('#surface').value,o=document.querySelector('#objective').value,t=document.querySelector('#travel').value;let out=races.filter(r=>(d==='any'||r.distance.toLowerCase().includes(d.toLowerCase())||(d==='Ultra'&&r.distance.includes('ultra')))&&(s==='any'||r.type===s)&&(t!=='carfree'||r.transport!=='Not confirmed'));out=out.slice(0,6);document.querySelector('#finder-results').innerHTML=out.map(r=>richCard({...r,reason:`${r.reason} ${objectiveCopy[o]||''}`})).join('')||'<p class="empty">No races meet those verified filters yet. Try a broader preference or leave travel as no preference.</p>';bind()};
render();

const shortlistKey='race-fieldnotes-shortlist';let shortlist=[];try{shortlist=JSON.parse(sessionStorage.getItem(shortlistKey)||'[]')}catch(e){shortlist=[]}
function saveShortlist(){try{sessionStorage.setItem(shortlistKey,JSON.stringify(shortlist.map(r=>r.name)))}catch(e){}}
function shortlistPanel(){let p=document.querySelector('#shortlist-panel');if(!p){p=document.createElement('section');p.id='shortlist-panel';p.className='section shortlist-section';p.innerHTML='<div class="split"><div><p class="eyebrow">04 / Your shortlist</p><h2>Keep the useful options.</h2></div><p>This shortlist stays in this browser session. Nothing is sent to a server.</p></div><div id="shortlist-list" class="cards"></div>';document.querySelector('#compare').before(p)}return p}
function renderShortlist(){const p=shortlistPanel(),list=p.querySelector('#shortlist-list');list.innerHTML=shortlist.length?shortlist.map(r=>`<article class="card shortlist-card"><span class="tag">Saved option</span><h3>${r.name}</h3><div class="meta">${r.distance} · ${r.place}</div><p>${r.reason}</p><a class="profile-link" href="/races/${slugify(r.name)}/">Open profile →</a> <button class="remove-save" data-name="${r.name}">Remove</button></article>`).join(''):'<p class="empty">Save up to six races from the directory or finder to compare them later.</p>';list.querySelectorAll('.remove-save').forEach(b=>b.onclick=()=>{shortlist=shortlist.filter(r=>r.name!==b.dataset.name);saveShortlist();renderShortlist()})}
function renderJourneyCompare(){const p=document.querySelector('#compare-panel');if(!chosen.length){p.innerHTML='<p>Select races using “Add to compare”.</p>';return}const unknown=chosen.filter(r=>r.cutoff==='Not confirmed').map(r=>r.name),travel=chosen.filter(r=>r.transport!=='Not confirmed').map(r=>r.name);p.innerHTML=`<div class="compare-heading"><p>${chosen.length}/3 selected</p><button class="clear-compare">Clear comparison</button></div><table class="compare-table"><tr><th>Detail</th>${chosen.map(x=>`<th>${x.name}<button class="remove-compare" data-name="${x.name}">×</button></th>`).join('')}</tr>${[['Distance','distance'],['Elevation','elevation'],['Cut-off','cutoff'],['Transport','transport'],['Facilities','facilities']].map(f=>`<tr><th>${f[0]}</th>${chosen.map(x=>`<td>${x[f[1]]}</td>`).join('')}</tr>`).join('')}</table><div class="comparison-summary"><strong>How to read this:</strong> ${travel.length?`${travel.join(', ')} ${travel.length===1?'has':'have'} some travel information.`:'No selected race has confirmed travel information.'} ${unknown.length?`${unknown.join(', ')} ${unknown.length===1?'has':'have'} no confirmed cut-off.`:'Every selected race has a reviewed cut-off field.'}</div>`;p.querySelector('.clear-compare').onclick=()=>{chosen=[];renderJourneyCompare()};p.querySelectorAll('.remove-compare').forEach(b=>b.onclick=()=>{chosen=chosen.filter(x=>x.name!==b.dataset.name);renderJourneyCompare()})}
const journeyBind=bind;bind=function(){journeyBind();document.querySelectorAll('.card').forEach(c=>{if(c.querySelector('.save-race'))return;const b=document.createElement('button');b.className='save-race';const name=c.querySelector('h3').textContent;b.dataset.name=name;b.textContent=shortlist.some(x=>x.name===name)?'Saved':'Save';b.onclick=()=>{const r=races.find(x=>x.name===name);if(!r)return;if(shortlist.some(x=>x.name===name))shortlist=shortlist.filter(x=>x.name!==name);else if(shortlist.length<6)shortlist.push(r);saveShortlist();renderShortlist();bind()};const compare=c.querySelector('.compare');if(compare)compare.before(b)});document.querySelectorAll('.compare').forEach(b=>b.onclick=()=>{const r=races.find(x=>x.name===b.dataset.name);if(r&&!chosen.some(x=>x.name===r.name)&&chosen.length<3)chosen.push(r);renderJourneyCompare()})};
renderShortlist();render();
